            /// <param name="x">the x coordinate where the top-left corner of the text will draw.</param>
            /// <param name="y">the y coordinate where the top-left corner of the text will draw.</param>
            /// <param name="str">the string to render.</param>
            /// <returns>
            ///   true on success or false on failure; call SDL_GetError() for more
            ///   information.
            /// </returns>
            /// <remarks>
            ///   <para>
            ///     This function will render a string of text to an SDL_Renderer. Note that
            ///     this is a convenience function for debugging, with severe limitations, and
            ///     not intended to be used for production apps and games.
            ///   </para>
            ///   <para>
            ///     Among these limitations:
            ///   </para>
            ///   <para>
            ///     - It accepts UTF-8 strings, but will only renders ASCII characters.
            ///     - It has a single, tiny size (8x8 pixels). You can use logical presentation
            ///     or SDL_SetRenderScale() to adjust it.
            ///     - It uses a simple, hardcoded bitmap font. It does not allow different font
            ///     selections and it does not support truetype, for proper scaling.
            ///     - It does no word-wrapping and does not treat newline characters as a line
            ///     break. If the text goes out of the window, it's gone.
            ///   </para>
            ///   <para>
            ///     For serious text rendering, there are several good options, such as
            ///     SDL_ttf, stb_truetype, or other external libraries.
            ///   </para>
            ///   <para>
            ///     On first use, this will create an internal texture for rendering glyphs.
            ///     This texture will live until the renderer is destroyed.
            ///   </para>
            ///   <para>
            ///     The text is drawn in the color specified by SDL_SetRenderDrawColor().
            ///   </para>
            /// </remarks>
            /// <threadsafety>
            ///   This function should only be called on the main thread.
            /// </threadsafety>
            /// <since>
            ///   This function is available since SDL 3.2.0.
            /// </since>
            public static bool RenderDebugText(SdlRenderer renderer, float x, float y, string str) =>
                PInvoke.RenderDebugText(renderer, x, y, str) != 0;

            /// <summary>
            ///   Set default scale mode for new textures for given renderer.
            /// </summary>
            /// <param name="renderer">the renderer to update.</param>
            /// <param name="scale_mode">the scale mode to change to for new textures.</param>
            /// <returns>
            ///   true on success or false on failure; call SDL_GetError() for more
            ///   information.
            /// </returns>
            /// <remarks>
            ///   <para>
            ///     When a renderer is created, scale_mode defaults to SDL_SCALEMODE_LINEAR.
            ///   </para>
            /// </remarks>
            /// <threadsafety>
            ///   This function should only be called on the main thread.
            /// </threadsafety>
            /// <since>
            ///   This function is available since SDL 3.4.0.
            /// </since>
            /// <seealso cref="Brutal.SdlApi.Sdl.PInvoke.GetDefaultTextureScaleMode"/>
            public static bool SetDefaultTextureScaleMode(SdlRenderer renderer, SdlScaleMode scale_mode) =>
                PInvoke.SetDefaultTextureScaleMode(renderer, scale_mode) != 0;

            /// <summary>
            ///   Get default texture scale mode of the given renderer.
            /// </summary>
            /// <param name="renderer">the renderer to get data from.</param>
            /// <param name="scale_mode">
            ///   a SDL_ScaleMode filled with current default scale mode.
            ///   See SDL_SetDefaultTextureScaleMode() for the meaning of
            ///   the value.
            /// </param>
            /// <returns>
            ///   true on success or false on failure; call SDL_GetError() for more
            ///   information.
            /// </returns>
            /// <threadsafety>
            ///   This function should only be called on the main thread.
            /// </threadsafety>
            /// <since>
            ///   This function is available since SDL 3.4.0.
            /// </since>
            /// <seealso cref="Brutal.SdlApi.Sdl.PInvoke.SetDefaultTextureScaleMode"/>
            public static bool GetDefaultTextureScaleMode(SdlRenderer renderer, out SdlScaleMode scale_mode)
            {
                scale_mode = default;
                fixed (SdlScaleMode* scale_modePtr = &scale_mode)
                {
                    return PInvoke.GetDefaultTextureScaleMode(renderer, scale_modePtr) != 0;
                }
            }

            /// <summary>
