            /// <seealso cref="Brutal.SdlApi.Sdl.PInvoke.DestroyGpuRenderState"/>
            public static nint CreateGpuRenderState(SdlRenderer renderer, SdlGpuRenderStateCreateInfo* createinfo) =>
                PInvoke.CreateGpuRenderState(renderer, createinfo);

            /// <summary>
            ///   Set fragment shader uniform variables in a custom GPU render state.
